/// Modulator table for a DSD rate multiple (64, 128, 256), an order (5..=8) and a
/// noise-shaping band (`wide`: the zeros spread to 22, 50 or 80 kHz).
pub(crate) fn modulator(rate_mult: u32, order: usize, wide: bool) -> Option<&'static ModTable> {
    match (rate_mult, order, wide) {
        (64, 5, true) => Some(&MOD_DSD64_O5),
        (64, 6, true) => Some(&MOD_DSD64_O6),
        (64, 7, true) => Some(&MOD_DSD64_O7),
        (64, 8, true) => Some(&MOD_DSD64_O8),
        (128, 5, true) => Some(&MOD_DSD128_O5),
        (128, 6, true) => Some(&MOD_DSD128_O6),
        (128, 7, true) => Some(&MOD_DSD128_O7),
        (128, 8, true) => Some(&MOD_DSD128_O8),
        (256, 5, true) => Some(&MOD_DSD256_O5),
        (256, 6, true) => Some(&MOD_DSD256_O6),
        (256, 7, true) => Some(&MOD_DSD256_O7),
        (256, 8, true) => Some(&MOD_DSD256_O8),
        (64, 5, false) => Some(&MOD_DSD64_A5),
        (64, 6, false) => Some(&MOD_DSD64_A6),
        (64, 7, false) => Some(&MOD_DSD64_A7),
        (64, 8, false) => Some(&MOD_DSD64_A8),
        (128, 5, false) => Some(&MOD_DSD128_A5),
        (128, 6, false) => Some(&MOD_DSD128_A6),
        (128, 7, false) => Some(&MOD_DSD128_A7),
        (128, 8, false) => Some(&MOD_DSD128_A8),
        (256, 5, false) => Some(&MOD_DSD256_A5),
        (256, 6, false) => Some(&MOD_DSD256_A6),
        (256, 7, false) => Some(&MOD_DSD256_A7),
        (256, 8, false) => Some(&MOD_DSD256_A8),
        _ => None,
    }
}
